<?php use App\Core\Config; ?>
<section class="page-heading"><div><p class="eyebrow">SEGURANCA OPERACIONAL</p><h1>Backups da aplicacao</h1><p>Copias privadas do banco e arquivos enviados. Restauracao exige procedimento controlado em ambiente seguro.</p></div></section>
<?php if (!empty($_SESSION['flash_success'])): ?><div class="flash flash-success"><?= htmlspecialchars((string) $_SESSION['flash_success']); unset($_SESSION['flash_success']); ?></div><?php endif; ?>
<?php if (!empty($_SESSION['flash_error'])): ?><div class="flash flash-error"><?= htmlspecialchars((string) $_SESSION['flash_error']); unset($_SESSION['flash_error']); ?></div><?php endif; ?>
<section class="card stack-gap"><div class="actions-row"><form method="post" action="<?= Config::url('/admin/backups/executar') ?>"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($_SESSION['_csrf'] ?? '') ?>"><button class="button button-primary" type="submit">Criar backup agora</button></form><?php if ($remoteConfigured): ?><form method="post" action="<?= Config::url('/admin/backups/testar-conexao') ?>"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($_SESSION['_csrf'] ?? '') ?>"><button class="button button-secondary" type="submit">Testar conexao remota</button></form><?php endif; ?></div><p class="muted">Destino remoto: <?= $remoteConfigured ? 'Google Drive configurado' : 'somente armazenamento local seguro' ?>.</p></section>
<section class="card"><div class="section-heading"><div><p class="eyebrow">HISTORICO</p><h2>Copias recentes</h2></div></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Tipo</th><th>Situacao</th><th>Arquivo</th><th>Remoto</th><th>Acoes</th></tr></thead><tbody><?php foreach ($backups as $backup): ?><tr><td><?= htmlspecialchars((string) ($backup['completed_at'] ?: $backup['started_at'])) ?></td><td><?= htmlspecialchars((string) $backup['type']) ?></td><td><?= htmlspecialchars((string) $backup['status']) ?></td><td><?= number_format((int) $backup['size_bytes'], 0, ',', '.') ?> bytes</td><td><?= htmlspecialchars((string) $backup['remote_status']) ?></td><td class="table-actions"><?php if (!empty($backup['local_path'])): ?><a class="button button-secondary button-small" href="<?= Config::url('/admin/backups/' . $backup['id'] . '/download') ?>">Baixar</a><?php endif; ?><?php if (($backup['remote_status'] ?? '') === 'failed'): ?><form method="post" action="<?= Config::url('/admin/backups/' . $backup['id'] . '/reenviar') ?>"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($_SESSION['_csrf'] ?? '') ?>"><button class="button button-secondary button-small">Reenviar</button></form><?php endif; ?><form method="post" action="<?= Config::url('/admin/backups/' . $backup['id'] . '/excluir') ?>" onsubmit="return confirm('Excluir backup? Esta acao nao pode ser desfeita.')"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($_SESSION['_csrf'] ?? '') ?>"><input type="hidden" name="confirmacao" value="EXCLUIR"><button class="button button-danger button-small">Excluir</button></form></td></tr><?php endforeach; ?><?php if (!$backups): ?><tr><td colspan="6">Nenhum backup registrado.</td></tr><?php endif; ?></tbody></table></div></section>
